-- Media and resident IT service domains for Negin Piroozi
CREATE TABLE IF NOT EXISTS media_library_items (id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,title TEXT NOT NULL,original_title TEXT,media_type TEXT NOT NULL CHECK(media_type IN ('movie','series','documentary','animation','education','cultural')),synopsis TEXT,release_year INTEGER,age_rating TEXT,runtime_minutes INTEGER,language TEXT,subtitle_languages_json TEXT,jellyfin_item_id TEXT,poster_storage_key TEXT,library_path TEXT,rights_basis TEXT NOT NULL,rights_verified_by TEXT REFERENCES people(id) ON DELETE SET NULL,rights_verified_at TEXT,visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','resident','family')),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','archived','blocked')),created_at TEXT NOT NULL,updated_at TEXT);
CREATE INDEX IF NOT EXISTS idx_media_items_building_status ON media_library_items(building_id,status,media_type);
CREATE TABLE IF NOT EXISTS media_profiles (id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,unit_id TEXT NOT NULL REFERENCES units(id) ON DELETE CASCADE,profile_name TEXT NOT NULL,age_group TEXT,parental_controls_json TEXT NOT NULL DEFAULT '{}',is_active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media_play_events (id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,profile_id TEXT REFERENCES media_profiles(id) ON DELETE SET NULL,media_item_id TEXT REFERENCES media_library_items(id) ON DELETE SET NULL,event_type TEXT NOT NULL CHECK(event_type IN ('started','progress','completed')),position_seconds INTEGER NOT NULL DEFAULT 0,occurred_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_media_play_profile_date ON media_play_events(profile_id,occurred_at);
CREATE TABLE IF NOT EXISTS it_support_tickets (id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,unit_id TEXT REFERENCES units(id) ON DELETE SET NULL,requester_name TEXT,requester_contact TEXT,category TEXT NOT NULL,device_type TEXT NOT NULL,subject TEXT NOT NULL,description TEXT NOT NULL,remote_support_requested INTEGER NOT NULL DEFAULT 0,remote_support_consent_at TEXT,status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','triaged','scheduled','in_progress','waiting_user','resolved','cancelled')),assigned_to TEXT REFERENCES people(id) ON DELETE SET NULL,created_at TEXT NOT NULL,updated_at TEXT);
CREATE INDEX IF NOT EXISTS idx_it_tickets_building_status ON it_support_tickets(building_id,status,created_at);
CREATE TABLE IF NOT EXISTS remote_support_sessions (id TEXT PRIMARY KEY,building_id TEXT NOT NULL REFERENCES buildings(id) ON DELETE CASCADE,ticket_id TEXT NOT NULL REFERENCES it_support_tickets(id) ON DELETE CASCADE,tool_name TEXT NOT NULL,session_code_hash TEXT,consented_by TEXT,consented_at TEXT NOT NULL,started_at TEXT,ended_at TEXT,operator_person_id TEXT REFERENCES people(id) ON DELETE SET NULL,session_log_key TEXT,status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','active','completed','revoked','expired')),created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_remote_sessions_ticket ON remote_support_sessions(ticket_id,status);